455	impl Eval for ast::MathArgs<'_> {
456	    type Output = Args;
457	
458	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
459	        // Math args need to fully separate named/pos to handle two-dimensional
460	        // args correctly, for example: `mat(a, delim:"[", b; c, d)`.
461	        let mut named = EcoVec::new();
462	        let mut pos = Vec::new();
463	        let mut two_dim_start: Option<usize> = None;
464	
465	        /// Optimize two-dimensional args by using `pos` as the sole container
466	        /// while iterating and only group into an array when we encounter a
467	        /// semicolon.
468	        fn drain_into_array(pos: &mut Vec<Arg>, start: usize, span: Span) {
469	            let array = pos.drain(start..).map(|arg| arg.value.v).collect();
470	            pos.push(Arg {
471	                span,
472	                name: None,
473	                value: Spanned::new(Value::Array(array), span),
474	            });
475	        }
476	
477	        for ast::MathArg { arg, ends_in_semicolon } in self.arg_items() {
478	            let span = arg.span();
479	            match arg {
480	                ast::Arg::Pos(expr) => {
481	                    pos.push(Arg {
482	                        span,
483	                        name: None,
484	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
485	                    });
486	                }
487	                ast::Arg::Named(named_arg) => {
488	                    let expr = named_arg.expr();
489	                    named.push(Arg {
490	                        span,
491	                        name: Some(named_arg.name().get().clone().into()),
492	                        value: Spanned::new(expr.eval(vm)?, expr.span()),
493	                    });
494	                }
495	                ast::Arg::Spread(spread) => match spread.expr().eval(vm)? {
496	                    Value::None => {}
497	                    Value::Array(array) => {
498	                        pos.extend(array.into_iter().map(|value| Arg {
499	                            span,
500	                            name: None,
501	                            value: Spanned::new(value, span),
502	                        }));
503	                    }
504	                    Value::Dict(dict) => {
505	                        named.extend(dict.into_iter().map(|(key, value)| Arg {
506	                            span,
507	                            name: Some(key),
508	                            value: Spanned::new(value, span),
509	                        }));
510	                    }
511	                    Value::Args(args) => {
512	                        for arg in args.items {
513	                            if arg.name.is_none() {
514	                                pos.push(arg);
515	                            } else {
516	                                named.push(arg);
517	                            }
518	                        }
519	                    }
520	                    v => bail!(spread.span(), "cannot spread {}", v.ty()),
521	                },
522	            }
523	            if ends_in_semicolon {
524	                let start = two_dim_start.unwrap_or(0);
525	                // There's not really a better span to use :/
526	                drain_into_array(&mut pos, start, self.span());
527	                two_dim_start = Some(pos.len());
528	            }
529	        }
530	
531	        if let Some(start) = two_dim_start
532	            && start != pos.len()
533	        {
534	            drain_into_array(&mut pos, start, self.span());
535	        }
536	
537	        named.extend(pos);
538	        Ok(Args { span: Span::detached(), items: named })
539	    }
540	}
